mapper.select:
select count(*)
from team t
WHERE COALESCE(t.deleted, false) = false

    AND t.sport IN

        #{sport}



	    AND (
		        t.gender = #{gender}
		        OR t.gender = '성별 무관'
		    )





                t.day_mon = true



                t.day_tue = true



                t.day_wed = true



                t.day_thu = true



                t.day_fri = true



                t.day_sat = true



                t.day_sun = true





    AND t.skill IN

        #{skill}



    AND (

            (
                t.region1 = #{region}
                OR t.region2 = #{region}
                OR t.region3 = #{region}
            )

    )


    AND (
        t.team_name LIKE CONCAT('%', #{keyword}, '%')
        OR t.description LIKE CONCAT('%', #{keyword}, '%')
    )

select t.*
from team_user tu
join team t on t.team_id = tu.team_id
where tu.user_id = #{userId}
  and tu.team_role in ('CAPTAIN', 'VICE_CAPTAIN')
  and tu.withdrawn = 0;
